end

function Window:SetVisible(show)
	show = show == true
	if self.Visible == show or self._animating then return end
	self.Visible = show
	self._animating = true
	if show then
		self.Gui.Enabled = true
		self:_resizeWindow(false)
		self.Frame.Size = UDim2.fromOffset(self.TargetSize.X - 24, self.TargetSize.Y - 16)
		self.Frame.GroupTransparency = 1
		self.Shade.BackgroundTransparency = 1
		self:_tween(self.Shade, 0.16, { BackgroundTransparency = 1 - (self.DimAmount / 100) })
		self:_tween(self.Frame, 0.22, {
			Size = UDim2.fromOffset(self.TargetSize.X, self.TargetSize.Y),
			GroupTransparency = 0,
		})
		task.wait(self.Animations and 0.2 or 0)
	else
		self:_tween(self.Shade, 0.14, { BackgroundTransparency = 1 })
		self:_tween(self.Frame, 0.16, {
			Size = UDim2.fromOffset(self.TargetSize.X - 16, self.TargetSize.Y - 12),
			GroupTransparency = 1,
		}, Enum.EasingStyle.Quart, Enum.EasingDirection.In)
		task.wait(self.Animations and 0.15 or 0)
		self.Gui.Enabled = false
	end
	self._animating = false
end

function Window:Toggle()
