function Window:SelectTab(tab)
	if type(tab) == "string" then tab = self._tabsByName[tab] end
	if not tab or tab == self.ActiveTab or self._switching then return end
	self._switching = true
	local previous = self.ActiveTab
	self.ActiveTab = tab
	for _, item in ipairs(self.Tabs) do
		local selected = item == tab
		self:_tween(item.Button, 0.16, {
			BackgroundColor3 = selected and THEME.AccentSoft or THEME.Panel,
		})
		self:_tween(item.Label, 0.16, {
			TextColor3 = selected and THEME.Text or THEME.Muted,
		})
		self:_tween(item.IconLabel, 0.16, {
			TextColor3 = selected and THEME.Text or THEME.Muted,
			BackgroundColor3 = selected and THEME.AccentSoft or THEME.Surface,
		})
		self:_tween(item.Indicator, 0.16, {
			BackgroundTransparency = selected and 0 or 1,
		})
	end
	self.PageTitle.Text = tab.Name
	self.PageSubtitle.Text = tab.Subtitle
	if previous then
		self:_tween(previous.Page, 0.12, {
			GroupTransparency = 1,
			Position = UDim2.fromOffset(-8, 0),
		})
		task.wait(self.Animations and 0.09 or 0)
		previous.Page.Visible = false
	end
	tab.Page.Visible = true
	tab.Page.GroupTransparency = self.Animations and 1 or 0
	tab.Page.Position = self.Animations and UDim2.fromOffset(10, 0) or UDim2.fromOffset(0, 0)
	self:_tween(tab.Page, 0.18, {
		GroupTransparency = 0,
		Position = UDim2.fromOffset(0, 0),
	})
	task.wait(self.Animations and 0.16 or 0)
	self._switching = false
end

function Window:AddTab(name, icon, subtitle)
	local tab = setmetatable({
		Window = self,
		Name = name,
		Icon = icon or "•",
		Subtitle = subtitle or "",
		Modules = {},
	}, Tab)
	tab.Page = create("CanvasGroup", {
		Name = name,
		Size = UDim2.fromScale(1, 1),
		BackgroundTransparency = 1,
		Visible = false,
		Parent = self.Content,
	})
	tab.Scroll = create("ScrollingFrame", {
		Name = name .. "List",
		Size = UDim2.fromScale(1, 1),
		Active = true,
		AutomaticCanvasSize = Enum.AutomaticSize.Y,
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
