		})
		if not silent then safeCall(self.Module.Window, callback, self.Value) end
	end
	control.Module = self
	self.Window:_connect(button.MouseButton1Click, function()
		control:SetValue(not control.Value)
	end)
	control:SetValue(control.Value, true)
	return control
