	window.Shade = create("Frame", {
		Name = "Shade",
		Size = UDim2.fromScale(1, 1),
		BackgroundColor3 = Color3.new(0, 0, 0),
		BackgroundTransparency = 1 - (window.DimAmount / 100),
		BorderSizePixel = 0,
		Parent = window.Gui,
	})
	window.Frame = create("CanvasGroup", {
		Name = "Window",
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromOffset(1040, 650),
		BackgroundColor3 = THEME.Background,
		BorderSizePixel = 0,
		ClipsDescendants = true,
		Parent = window.Gui,
	}, {
		corner(18),
		stroke(THEME.Border, 0.12),
		create("UISizeConstraint", {
			MinSize = Vector2.new(760, 470),
			MaxSize = Vector2.new(1180, 720),
		}),
	})
	local sidebar = create("Frame", {
		Name = "Sidebar",
		Size = UDim2.new(0, 220, 1, 0),
		BackgroundColor3 = THEME.Panel,
		BorderSizePixel = 0,
		Parent = window.Frame,
	})
	create("Frame", {
		AnchorPoint = Vector2.new(1, 0),
		Position = UDim2.new(1, 0, 0, 0),
		Size = UDim2.new(0, 1, 1, 0),
		BackgroundColor3 = THEME.Border,
		BackgroundTransparency = 0.28,
		BorderSizePixel = 0,
		Parent = sidebar,
	})
	local brand = create("Frame", {
		Size = UDim2.new(1, 0, 0, 96),
