		Font = Enum.Font.GothamMedium,
		TextSize = 24,
		Parent = topbar,
	}, { corner(9), stroke(THEME.Border, 0.45) })
	window:_hover(closeButton, THEME.PanelRaised, THEME.DangerSurface)
	window:_connect(closeButton.MouseButton1Click, function() window:SetVisible(false) end)
	window.Content = create("Frame", {
		Position = UDim2.fromOffset(32, 92),
		Size = UDim2.new(1, -64, 1, -124),
		BackgroundTransparency = 1,
		ClipsDescendants = true,
		Parent = main,
	})
	window:_makeDraggable(window.Frame, topbar)
	local function updateSize() window:_resizeWindow(false) end
	updateSize()
	if workspace.CurrentCamera then
		window:_connect(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"), updateSize)
	end
	window:_connect(UserInputService.InputBegan, function(input, processed)
		window:_handleKeyboard(input, processed)
	end)
	window.TargetSize = window:_targetWindowSize()
	window.Frame.Size = UDim2.fromOffset(window.TargetSize.X - 24, window.TargetSize.Y - 16)
	window.Frame.GroupTransparency = 1
	window.Shade.BackgroundTransparency = 1
	window:_tween(window.Shade, 0.18, { BackgroundTransparency = 1 - (window.DimAmount / 100) })
	window:_tween(window.Frame, 0.24, {
		Size = UDim2.fromOffset(window.TargetSize.X, window.TargetSize.Y),
		GroupTransparency = 0,
	})
	window:_applyTextScale()
	return window
end

function Library.new(options)
	return Library:CreateWindow(options)
end

Library.Theme = THEME
Library.Themes = THEMES

return Library
